--- HTTP Request Module for Virtual CLU
-- This module provides HTTP request functionality compatible with Object Manager.
-- It supports various HTTP methods (GET, POST, etc.), request/response types (JSON, XML, FormData),
-- custom headers, query parameters, and asynchronous request handling with event callbacks.
--
-- @module HTTPRequest
-- @author Autogenerated code: HTTPRequest, interface: object_http_request_v1.xml
-- @usage
--   local req = HTTPRequest:new("req1", "192.168.1.100", eventBus)
--   req:set(HTTPRequest.FEATURE_HOST, "http://example.com")
--   req:set(HTTPRequest.FEATURE_PATH, "/api/data")
--   req:set(HTTPRequest.FEATURE_METHOD, "GET")
--   req:add_event(HTTPRequest.EVENT_ON_RESPONSE, function() print("Response received") end)
--   req:execute(HTTPRequest.METHOD_SEND_REQUEST)

HTTPRequest = {}

-- ============================================
-- Feature Constants
-- ============================================
-- These constants are used with set() and get() methods to access object properties

--- Host address feature constant (settable)
HTTPRequest.FEATURE_HOST = 0

--- Path feature constant (settable)
HTTPRequest.FEATURE_PATH = 1

--- Query string parameters feature constant (settable)
-- Use \z to indicate no content
HTTPRequest.FEATURE_QUERY_STRING_PARAMS = 2

--- HTTP method feature constant (settable)
-- E.g., "GET", "POST", "PUT", "DELETE"
HTTPRequest.FEATURE_METHOD = 3

--- Request timeout feature constant (settable)
-- Timeout in seconds
HTTPRequest.FEATURE_TIMEOUT = 4

--- Request content type feature constant (settable)
-- Defines the content-type header parameter. RequestBody is serialized based on this type:
-- 0 - None: content-type not sent, RequestBody not serialized
-- 1 - Text: content-type text/plain, RequestBody not serialized
-- 2 - JSON: content-type application/json, RequestBody serialized to JSON
-- 3 - XML: content-type text/xml, RequestBody serialized to XML
-- 4 - FormData: content-type application/x-www-form-urlencoded, RequestBody serialized to table
-- 5 - Other: custom content-type, define in RequestHeaders, RequestBody not serialized
HTTPRequest.FEATURE_REQUEST_TYPE = 5

--- Response content type feature constant (settable)
-- Defines the Accept header parameter. ResponseBody is parsed based on this type:
-- 0 - None: Accept not sent, ResponseBody not parsed
-- 1 - Text: Accept text/plain, ResponseBody not parsed
-- 2 - JSON: Accept application/json, ResponseBody parsed from JSON
-- 3 - XML: Accept text/xml, ResponseBody parsed from XML
-- 4 - FormData: Accept application/x-www-form-urlencoded, ResponseBody parsed
-- 5 - Other: custom Accept header, define in RequestHeaders
HTTPRequest.FEATURE_RESPONSE_TYPE = 6

--- Request headers feature constant (settable)
-- Additional HTTP request headers. Use \z to indicate no content
HTTPRequest.FEATURE_REQUEST_HEADERS = 7

--- Request body feature constant (settable)
-- Message content to send in request. Use \z to indicate no content
HTTPRequest.FEATURE_REQUEST_BODY = 8

--- Response body feature constant (read-only)
-- Message content received after sending request
HTTPRequest.FEATURE_RESPONSE_BODY = 10

--- HTTP status code feature constant (read-only)
-- HTTP response status code (e.g., 200, 404, 500)
HTTPRequest.FEATURE_STATUS_CODE = 11

-- ============================================
-- Request Type Constants
-- ============================================
-- Used with FEATURE_REQUEST_TYPE to define content serialization

--- No content type (content-type not sent, no serialization)
HTTPRequest.REQUEST_TYPE_NONE = 0

--- Plain text content type (content-type: text/plain, no serialization)
HTTPRequest.REQUEST_TYPE_TEXT = 1

--- JSON content type (content-type: application/json, body serialized to JSON)
HTTPRequest.REQUEST_TYPE_JSON = 2

--- XML content type (content-type: text/xml, body serialized to XML)
HTTPRequest.REQUEST_TYPE_XML = 3

--- Form data content type (content-type: application/x-www-form-urlencoded, body serialized to form)
HTTPRequest.REQUEST_TYPE_FORM_DATA = 4

--- Custom content type (define in headers, no serialization)
HTTPRequest.REQUEST_TYPE_OTHER = 5

-- ============================================
-- Response Type Constants
-- ============================================
-- Used with FEATURE_RESPONSE_TYPE to define response parsing

--- No response parsing (Accept not sent)
HTTPRequest.RESPONSE_TYPE_NONE = 0

--- Plain text response (Accept: text/plain, no parsing)
HTTPRequest.RESPONSE_TYPE_TEXT = 1

--- JSON response (Accept: application/json, parsed from JSON)
HTTPRequest.RESPONSE_TYPE_JSON = 2

--- XML response (Accept: text/xml, parsed from XML)
HTTPRequest.RESPONSE_TYPE_XML = 3

--- Form data response (Accept: application/x-www-form-urlencoded, parsed)
HTTPRequest.RESPONSE_TYPE_FORM_DATA = 4

--- Custom response type (define Accept in headers)
HTTPRequest.RESPONSE_TYPE_OTHER = 5

-- ============================================
-- Method Constants
-- ============================================
-- Used with execute() to perform actions

--- Send HTTP request
HTTPRequest.METHOD_SEND_REQUEST = 0

--- Abort request in progress
HTTPRequest.METHOD_ABORT_REQUEST = 1

--- Clear all request data
HTTPRequest.METHOD_CLEAR = 2

-- ============================================
-- Event Constants
-- ============================================
-- Used with add_event() to register callbacks

--- Event triggered when request is sent
HTTPRequest.EVENT_ON_REQUEST_SENT = 0

--- Event triggered when response is received
HTTPRequest.EVENT_ON_RESPONSE = 1

-- ============================================
-- Other Constants
-- ============================================

--- Empty value marker (indicates no content)
HTTPRequest.EMPTY_VALUE = "\z"

-- Request ID counter for async tracking
HTTPRequest._nextRequestId = 1

--- Generate unique request ID for async tracking
-- @return string Unique request identifier
function HTTPRequest:_generateRequestId()
    local id = "http_" .. tostring(self.id) .. "_" .. HTTPRequest._nextRequestId
    HTTPRequest._nextRequestId = HTTPRequest._nextRequestId + 1
    return id
end

--- Create a new HTTPRequest instance
-- @param id string Unique identifier for this HTTPRequest object
-- @param address string Network address (optional, can be nil)
-- @param eventBus table Event bus instance for event handling
-- @return table New HTTPRequest instance
-- @usage local req = HTTPRequest:new("myRequest", "192.168.1.100", eventBus)
function HTTPRequest:new(id, address, eventBus)

    if (id == nil) then
        error("HTTPRequest: missing id")
    end

    if (eventBus == nil) then
        error("HTTPRequest: missing eventBus")
    end

    local httprequest = {
        id = id,
        description = "HTTPRequest",
        index = index,
        address = address,
        eventBus = eventBus,

        host = "",
        path = "",
        queryStringParams = HTTPRequest.EMPTY_VALUE,
        method = "GET",
        timeout = 5,
        requestType = 1,
        responseType = 1,
        requestHeaders = HTTPRequest.EMPTY_VALUE,
        requestBody = HTTPRequest.EMPTY_VALUE,
        responseBody = HTTPRequest.EMPTY_VALUE,
        statusCode = 0,

        status = "waiting",
        responseBodyTxt = HTTPRequest.EMPTY_VALUE,
    }

    setmetatable(httprequest, self)
    self.__index = self

    return httprequest
end

-- ============================================
-- Helper methods for HTTP request building
-- ============================================

--- Build complete URL from host, path, and query parameters
-- @return string Complete URL with protocol, path, and query string
function HTTPRequest:_buildUrl()
    local url = self.host or ""

    -- Add protocol if missing
    if url ~= "" and not url:match("^https?://") then
        url = "http://" .. url
    end

    -- Add path
    if self.path and self.path ~= "" then
        if url:sub(-1) == "/" and self.path:sub(1, 1) == "/" then
            url = url .. self.path:sub(2)
        elseif url:sub(-1) ~= "/" and self.path:sub(1, 1) ~= "/" then
            url = url .. "/" .. self.path
        else
            url = url .. self.path
        end
    end

    -- Add query params
    if self.queryStringParams and self.queryStringParams ~= self.EMPTY_VALUE then
        local queryStr = ""
        if type(self.queryStringParams) == "table" then
            local params = {}
            for k, v in pairs(self.queryStringParams) do
                table.insert(params, tostring(k) .. "=" .. tostring(v))
            end
            queryStr = table.concat(params, "&")
        elseif type(self.queryStringParams) == "string" then
            queryStr = self.queryStringParams
        end

        if queryStr ~= "" then
            if url:find("?") then
                url = url .. "&" .. queryStr
            else
                url = url .. "?" .. queryStr
            end
        end
    end

    return url
end

--- Build HTTP headers based on request/response types and custom headers
-- @return table HTTP headers map (key-value pairs)
function HTTPRequest:_buildHeaders()
    local headers = {}

    -- Content-Type based on RequestType
    local contentTypes = {
        [0] = nil,  -- None
        [1] = "text/plain",
        [2] = "application/json",
        [3] = "text/xml",
        [4] = "application/x-www-form-urlencoded",
        [5] = nil,  -- Other - user must set in requestHeaders
    }

    if contentTypes[self.requestType] then
        headers["Content-Type"] = contentTypes[self.requestType]
    end

    -- Accept based on ResponseType
    local acceptTypes = {
        [0] = nil,
        [1] = "text/plain",
        [2] = "application/json",
        [3] = "text/xml",
        [4] = "application/x-www-form-urlencoded",
        [5] = nil,
    }

    if acceptTypes[self.responseType] then
        headers["Accept"] = acceptTypes[self.responseType]
    end

    -- Merge user headers
    if self.requestHeaders and self.requestHeaders ~= self.EMPTY_VALUE then
        if type(self.requestHeaders) == "table" then
            for k, v in pairs(self.requestHeaders) do
                headers[k] = v
            end
        end
    end

    return headers
end

--- Serialize request body based on request type
-- @return string Serialized body content ready for transmission
function HTTPRequest:_serializeBody()
    if self.requestBody == nil or self.requestBody == self.EMPTY_VALUE then
        return ""
    end

    -- JSON serialization
    if self.requestType == self.REQUEST_TYPE_JSON and type(self.requestBody) == "table" then
        if JSON and JSON.encode then
            return JSON.encode(self.requestBody)
        end
    end

    -- FormData serialization
    if self.requestType == self.REQUEST_TYPE_FORM_DATA and type(self.requestBody) == "table" then
        local parts = {}
        for k, v in pairs(self.requestBody) do
            table.insert(parts, tostring(k) .. "=" .. tostring(v))
        end
        return table.concat(parts, "&")
    end

    -- Text, XML, Other - return as string
    return tostring(self.requestBody)
end

-- ============================================
-- Response handling
-- ============================================

--- Start polling for async HTTP response
-- Polls the Go backend at 100ms intervals until response is received or timeout occurs.
-- Uses recursive setTimeout calls to check for response completion.
-- Automatically stops polling if request is aborted or timeout is reached.
function HTTPRequest:_startResponsePolling()
    local pollCount = 0
    local maxPolls = math.ceil((self.timeout * 1000) / 100)  -- 100ms per poll
    local requestId = self._requestId
    local self_ref = self  -- capture reference for closure

    local function checkResponse()
        -- Check if request was aborted
        if self_ref._requestId ~= requestId then
            Logger:getShared():debug("[HTTPRequest] %s: polling stopped (aborted or new request)", self_ref.id)
            return
        end

        pollCount = pollCount + 1

        -- Use __go_http_poll_async to check if any request completed
        local completedId = __go_http_poll_async()
        if completedId == requestId then
            -- Our request completed, get the response
            local status, body, headersJson, err = __go_http_get_async_response(requestId)
            if status ~= nil then
                self_ref:_handleResponse(status, body, headersJson, err)
                return
            end
        elseif completedId then
            -- Some other request completed, ignore it (put it back? No, it's gone)
            Logger:getShared():debug("[HTTPRequest] %s: ignoring completed request %s", self_ref.id, completedId)
        end

        if pollCount >= maxPolls then
            Logger:getShared():warn("[HTTPRequest] %s: timeout after %d polls", self_ref.id, pollCount)
            self_ref:_handleResponse(0, "", "{}", "timeout")
            return
        end

        -- Continue polling using Go timer
        if __go_setTimeout then
            __go_setTimeout(checkResponse, 100)
        end
    end

    -- Start first poll after 100ms
    if __go_setTimeout then
        __go_setTimeout(checkResponse, 100)
    else
        Logger:getShared():error("[HTTPRequest] __go_setTimeout not available")
        self:_handleResponse(0, "", "{}", "timer not available")
    end
end

--- Handle HTTP response and parse body based on response type
-- @param status number HTTP status code (0 if error)
-- @param body string Raw response body
-- @param headersJson string Response headers as JSON string
-- @param err string Error message (nil if successful)
function HTTPRequest:_handleResponse(status, body, headersJson, err)
    self.statusCode = status or 0
    self.responseBodyTxt = body or ""

    -- Parse response based on ResponseType
    if self.responseType == self.RESPONSE_TYPE_NONE then
        self.responseBody = body
    elseif self.responseType == self.RESPONSE_TYPE_TEXT then
        self.responseBody = body
    elseif self.responseType == self.RESPONSE_TYPE_JSON then
        if JSON and JSON.decode and body and body ~= "" then
            local ok, parsed = pcall(JSON.decode, body)
            if ok and parsed ~= nil then
                self.responseBody = parsed
            else
                self.responseBody = body
            end
        else
            self.responseBody = body
        end
    elseif self.responseType == self.RESPONSE_TYPE_XML then
        if __xml and __xml.parseXML and body and body ~= "" then
            local ok, parsed = pcall(__xml.parseXML, body)
            if ok and parsed ~= nil then
                self.responseBody = parsed
            else
                self.responseBody = body
            end
        else
            self.responseBody = body
        end
    elseif self.responseType == self.RESPONSE_TYPE_FORM_DATA then
        -- Parse form data
        if body and body ~= "" then
            local parsed = {}
            for pair in body:gmatch("[^&]+") do
                local key, value = pair:match("([^=]+)=?(.*)")
                if key then
                    parsed[key] = value or ""
                end
            end
            self.responseBody = parsed
        else
            self.responseBody = {}
        end
    else
        self.responseBody = body
    end

    if err then
        self.status = "error"
        Logger:getShared():error("[HTTPRequest] %s: %s", self.id, tostring(err))
    else
        self.status = "done"
    end

    -- Fire OnResponse event
    self.eventBus:fire(self, HTTPRequest.EVENT_ON_RESPONSE)
end

