--- Set a feature value
-- @param key number Feature constant (FEATURE_HOST, FEATURE_PATH, etc.)
-- @param value any Value to set (type depends on the feature)
-- @return table Self for method chaining
-- @usage req:set(HTTPRequest.FEATURE_HOST, "http://example.com")
function HTTPRequest:set(key, value)

    if (value == nil) then
        error("HTTPRequest:set(" .. key .. ", nil")
    end

        if (0 == key) then Logger.getShared():info("HTTPRequest:set(FEATURE_SET_HOST, ".. value ..")") end
        if (1 == key) then Logger.getShared():info("HTTPRequest:set(FEATURE_SET_PATH, ".. value ..")") end
        if (2 == key) then Logger.getShared():info("HTTPRequest:set(FEATURE_SET_QUERY_STRING_PARAMS") end -- czy tu moze byc array?
        if (3 == key) then Logger.getShared():info("HTTPRequest:set(FEATURE_SET_METHOD, ".. value ..")") end
        if (4 == key) then Logger.getShared():info("HTTPRequest:set(FEATURE_SET_TIMEOUT, ".. value ..")") end
        if (5 == key) then Logger.getShared():info("HTTPRequest:set(FEATURE_SET_REQUEST_TYPE, ".. value ..")") end
        if (6 == key) then Logger.getShared():info("HTTPRequest:set(FEATURE_SET_RESPONSE_TYPE, ".. value ..")") end
        if (7 == key) then Logger.getShared():info("HTTPRequest:set(FEATURE_SET_REQUEST_HEADERS") end -- to moga byc array
        if (8 == key) then Logger.getShared():info("HTTPRequest:set(FEATURE_SET_REQUEST_BODY") end -- array
        if (10 == key) then Logger.getShared():info("HTTPRequest:set(FEATURE_SET_RESPONSE_BODY") end -- array


    if (HTTPRequest.FEATURE_HOST == key) then
        self.host = value
        return self
    end

    if (HTTPRequest.FEATURE_PATH == key) then
        self.path = value
        return self
    end

    if (HTTPRequest.FEATURE_QUERY_STRING_PARAMS == key) then
        self.queryStringParams = value
        return self
    end

    if (HTTPRequest.FEATURE_METHOD == key) then
        self.method = value
        return self
    end

    if (HTTPRequest.FEATURE_TIMEOUT == key) then
        self.timeout = value
        return self
    end

    if (HTTPRequest.FEATURE_REQUEST_TYPE == key) then
        if (value < 0) then
            error('FEATURE_REQUEST_TYPE type < 0')
        end

        if (value > 5) then
            error('FEATURE_REQUEST_TYPE type > 5')
        end
        self.requestType = value
        return self
    end

    if (HTTPRequest.FEATURE_RESPONSE_TYPE == key) then
        if (value < 0) then
            error('FEATURE_RESPONSE_TYPE type < 0')
        end

        if (value > 5) then
            error('FEATURE_RESPONSE_TYPE type > 5')
        end
        self.responseType = value
        return self
    end

    if (HTTPRequest.FEATURE_REQUEST_HEADERS == key) then
        self.requestHeaders = value
        return self
    end

    if (HTTPRequest.FEATURE_REQUEST_BODY == key) then
        self.requestBody = value
        return self
    end

    if (HTTPRequest.FEATURE_RESPONSE_BODY == key) then
        self.responseBody = value
        return self
    end

    error("not recognized set key: " .. key)
end

--- Get a feature value
-- @param key number Feature constant (FEATURE_HOST, FEATURE_PATH, etc.)
-- @return any Feature value (type depends on the feature)
-- @usage local host = req:get(HTTPRequest.FEATURE_HOST)
function HTTPRequest:get(key)

    if (HTTPRequest.FEATURE_HOST == key) then
        -- Adres hosta
        return self.host
    end

    if (HTTPRequest.FEATURE_PATH == key) then
        -- Ścieżka zapytania
        return self.path
    end

    if (HTTPRequest.FEATURE_QUERY_STRING_PARAMS == key) then
        -- Parametry zapytania. \z oznacza brak
        return self.queryStringParams
    end

    if (HTTPRequest.FEATURE_METHOD == key) then
        -- Typ metody wysyłanej w zapytaniu np. GET, POST
        return self.method
    end

    if (HTTPRequest.FEATURE_TIMEOUT == key) then
        -- Dopuszczalny czas odpowiedzi
        return self.timeout
    end

    if (HTTPRequest.FEATURE_REQUEST_TYPE == key) then
        -- Typ zawartości wysyłanego zapytania.
        -- Definiuje parametr content-type w nagłówku zapytania. W zależności od wybranego typu zawartość cechy RequestBody jest odpowiednio serializowana:
        -- 0 - None - niezdefiniowany. W nagłówku nie jest wysyłane content-type. Zawartość cechy RequestBody nie jest serializowana.
        -- 1 - Text - content-type: text/plain. Zawartość cechy RequestBody nie jest serializowana.
        -- 2 - JSON - content-type: application/json. Zawartość cechy RequestBody jest serializowana do formatu JSON.
        -- 3 - XML - content-type: text/xml. Zawartość cechy RequestBody jest serializowana do formatu XML.
        -- 4 - FormData - content-type: application/x-www-form-urlencoded. Zawartość cechy RequestBody jest serializowana do tabeli.
        -- 5 - Other - typ zawartości (content-type) jest inny niż wbudowany. Typ można zdefinować umieszczając go w nagłówku (cecha RequestHeaders). Zawartość nie jest serializowana.
        return self.requestType
    end

    if (HTTPRequest.FEATURE_RESPONSE_TYPE == key) then
        -- Typ oczekiwanej odpowiedzi. Definiuje parametr Accept w nagłówku zapytania.
        -- W zależności od wybranego typu zawartość otrzymanej odpowiedzi (cechy ResponseBody) jest odpowiednio parsowana do tabeli:
        -- 0 - None - parametr Accept nie jest wysyłany w nagłowku wysyłanego zapytania. Odpowiedź (cecha ResponseBody) nie jest parsowana.
        -- 1 - Text - Accept: text/plain. Odpowiedź (cecha ResponseBody) nie jest parsowana.
        -- 2 - JSON - Accept: application/json. Odpowiedź (cecha ResponseBody) jest parsowana z JSON.
        -- 3 - XML - Accept: text/xml. Odpowiedź (cecha ResponseBody) jest parsowana z XML.
        -- 4 - FormData - Accept: application/x-www-form-urlencoded. Odpowiedź (cecha ResponseBody) jest parsowana.
        -- 5 - Other - parametr Accept nagłówka jest inny niż wbudowany. Parametr można zdefinować umieszczając go w nagłówku (cecha RequestHeaders)
        return self.responseType
    end

    if (HTTPRequest.FEATURE_REQUEST_HEADERS == key) then
        -- Dodatkowe nagłówki zapytania HTTP. \z oznacza brak zawartości. 
        return self.requestHeaders
    end

    if (HTTPRequest.FEATURE_REQUEST_BODY == key) then
        -- Zawartość wiadomości wysyłanej w zapytaniu. \z oznacza brak zawartości
        return self.requestBody
    end

    if (HTTPRequest.FEATURE_RESPONSE_BODY == key) then
        -- Zawartość wiadomości otrzymanej po wysłaniu zapytania (cecha wykorzystywana do odczytu w skryptach - nieustawialna)
        return self.responseBody
    end

    if (HTTPRequest.FEATURE_STATUS_CODE == key) then
        -- Status odpowiedzi HTTP
        return self.statusCode
    end

    error("not recognized get key")

end

--- Execute a method
-- @param key number Method constant (METHOD_SEND_REQUEST, METHOD_ABORT_REQUEST, METHOD_CLEAR)
-- @param value any Optional parameter for the method (currently unused)
-- @usage req:execute(HTTPRequest.METHOD_SEND_REQUEST)
function HTTPRequest:execute(key, value)
    -- Debug logging
    if key == HTTPRequest.METHOD_SEND_REQUEST then
        Logger:getShared():info("[HTTPRequest] %s: SendRequest", self.id)
    elseif key == HTTPRequest.METHOD_ABORT_REQUEST then
        Logger:getShared():info("[HTTPRequest] %s: AbortRequest", self.id)
    elseif key == HTTPRequest.METHOD_CLEAR then
        Logger:getShared():info("[HTTPRequest] %s: Clear", self.id)
    end

    -- SendRequest - wysyła żądanie HTTP
    if key == HTTPRequest.METHOD_SEND_REQUEST then
        -- Build URL from host + path + queryParams
        local url = self:_buildUrl()

        -- Build headers
        local headers = self:_buildHeaders()

        -- Serialize body based on RequestType
        local body = self:_serializeBody()

        -- Generate unique request ID for async tracking
        self._requestId = self:_generateRequestId()
        self.status = "sending"

        Logger:getShared():debug("[HTTPRequest] %s: %s %s", self.id, self.method, url)

        -- Fire OnRequestSent event
        self.eventBus:fire(self, HTTPRequest.EVENT_ON_REQUEST_SENT)

        -- Check if Go HTTP backend is available
        if not __go_http_async_request then
            Logger:getShared():error("[HTTPRequest] __go_http_async_request not available")
            self:_handleResponse(0, "", "{}", "HTTP backend not available")
            return
        end

        -- Send async HTTP request via Go backend
        local headersJson = "{}"
        if JSON and JSON.encode then
            headersJson = JSON.encode(headers)
        end

        __go_http_async_request(
            self.id,                    -- instanceId
            self._requestId,            -- requestId
            self.method or "GET",       -- method
            url,                        -- url
            headersJson,                -- headers as JSON
            body,                       -- body
            (self.timeout or 5) * 1000, -- timeout in ms
            true,                       -- verifySSL
            true                        -- followRedirects
        )

        -- Start polling for response
        self:_startResponsePolling()
        return
    end

    -- AbortRequest - przerywa żądanie
    if key == HTTPRequest.METHOD_ABORT_REQUEST then
        if self.status == "sending" then
            self.status = "aborted"
            self._requestId = nil  -- Stop polling
        end
        return
    end

    -- Clear - czyści wszystkie pola
    if key == HTTPRequest.METHOD_CLEAR then
        self.host = ""
        self.path = ""
        self.queryStringParams = self.EMPTY_VALUE
        self.method = "GET"
        self.timeout = 5
        self.requestType = 1
        self.responseType = 1
        self.requestHeaders = self.EMPTY_VALUE
        self.requestBody = self.EMPTY_VALUE
        self.responseBody = self.EMPTY_VALUE
        self.statusCode = 0
        self.status = "waiting"
        self.responseBodyTxt = self.EMPTY_VALUE
        self._requestId = nil
        return
    end
end

--- Register an event callback
-- @param eventName number Event constant (EVENT_ON_REQUEST_SENT, EVENT_ON_RESPONSE)
-- @param callback function Callback function to execute when event fires
-- @usage req:add_event(HTTPRequest.EVENT_ON_RESPONSE, function() print("Done!") end)
function HTTPRequest:add_event(eventName, callback)
    self.eventBus:on(self, eventName, callback)
end

--- Get current state as table (for serialization/inspection)
-- @return table Object state with all properties
function HTTPRequest:__getState()
    return {
        id = self.id,
        address = self.address,
        type = 'HTTPRequest',
        host = self:get(HTTPRequest.FEATURE_HOST),
        path = self:get(HTTPRequest.FEATURE_PATH),
        queryStringParams = self:get(HTTPRequest.FEATURE_QUERY_STRING_PARAMS),
        method = self:get(HTTPRequest.FEATURE_METHOD),
        timeout = self:get(HTTPRequest.FEATURE_TIMEOUT),
        requestType = self:get(HTTPRequest.FEATURE_REQUEST_TYPE),
        responseType = self:get(HTTPRequest.FEATURE_RESPONSE_TYPE),
        requestHeaders = self:get(HTTPRequest.FEATURE_REQUEST_HEADERS),
        requestBody = self:get(HTTPRequest.FEATURE_REQUEST_BODY),
        responseBody = self:get(HTTPRequest.FEATURE_RESPONSE_BODY),
        statusCode = self:get(HTTPRequest.FEATURE_STATUS_CODE),

        status = self.status, -- to moj zmyslony
        responseBodyTxt = self.responseBodyTxt -- to tez moj zmyslony
    }
end

--- Set HTTP response (internal method for legacy compatibility)
-- Note: Body must be base64 encoded to avoid escaping issues
-- @param code number HTTP status code
-- @param bodyBase64 string Base64-encoded response body
function HTTPRequest:__setResponse(code, bodyBase64)
    if (code == nil) then code = 0 end
    if (bodyBase64 == nil) then bodyBase64 = "" end -- zeby uniknac jakis dziwnych bledow

    self.statusCode = code

    local tmpBody = base64.decode(bodyBase64)
    self.responseBodyTxt = tmpBody

    if (self.responseType == HTTPRequest.RESPONSE_TYPE_NONE) then
        self.responseBody = tmpBody
    end

    if (self.responseType == HTTPRequest.RESPONSE_TYPE_TEXT) then
        self.responseBody = tmpBody
    end

    if (self.responseType == HTTPRequest.RESPONSE_TYPE_JSON) then
        self.responseBody = json.decode(tmpBody)
    end

    if (self.responseType == HTTPRequest.RESPONSE_TYPE_XML) then
        self.responseBody = __xml.parseXML(tmpBody)
    end

    if (self.responseType == HTTPRequest.RESPONSE_TYPE_FORM_DATA) then
        error("FORM_DATA response not implemented yet!")
        --
        -- https://stackoverflow.com/questions/4007969/application-x-www-form-urlencoded-or-multipart-form-data
        --
    end

    if (self.responseType == HTTPRequest.RESPONSE_TYPE_OTHER) then
        self.responseBody = tmpBody
    end

    self.status = "done" -- to jest moj wewnetrzny status
    self.eventBus:fire(self, HTTPRequest.EVENT_ON_RESPONSE)
end

return HTTPRequest
